     1	// line-chart — a bundled template (spec §11 G-44): `values` as a
     2	// comma-separated string, a line drawn on through its points, a dot popping
     3	// at each, an area fill behind and the last value called out.
     4	export const meta = {
     5	  name: "Line chart",
     6	  durationInFrames: 150,
     7	};
     8	
     9	export const schema = {
    10	  values: { type: "string",  default: "12, 18, 15, 26, 22, 34, 41", animate: false },
    11	  labels: { type: "string",  default: "Jan, Feb, Mar, Apr, May, Jun, Jul", animate: false },
    12	  title:  { type: "string",  default: "Monthly active users" },
    13	  area:   { type: "boolean", default: true },
    14	  accent: { type: "color",   default: "#2d7ff9" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const D = ctx.durationInFrames;
    20	  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v));
    21	  const labels = props.labels.split(",").map((l) => l.trim());
    22	  const n = values.length;
    23	  const safeX = ctx.width * 0.05;
    24	  const safeY = ctx.height * 0.05;
    25	  const safeW = ctx.width * 0.9;
    26	  const safeH = ctx.height * 0.9;
    27	  const pad = 60 * u;
    28	  const innerW = safeW - 2 * pad;
