    85	      <text x="${cx}" y="${cy + R * 0.66 + 54 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800"
    86	            font-size="${34 * u}" fill="#d8d8e0">${escapeXml(props.units)}</text>
    87	    </g>`);
    88	}
=== progress-bar
     1	// progress-bar — a bundled template (spec §11 G-44): a labelled track on a
     2	// plate, wiped in from the left, its fill growing to `value` with the
     3	// percentage counting and one shine sweeping across.
     4	export const meta = {
     5	  name: "Progress bar",
     6	  durationInFrames: 120,
     7	};
     8	
     9	export const schema = {
    10	  value:       { type: "number",  default: 68, min: 0, max: 100, step: 1 },
    11	  label:       { type: "string",  default: "Rendering" },
    12	  showPercent: { type: "boolean", default: true },
    13	  position:    { type: "enum",    default: "bottom", options: ["bottom", "center", "top"] },
    14	  accent:      { type: "color",   default: "#2d7ff9" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const D = ctx.durationInFrames;
    20	  const safeX = ctx.width * 0.05;
    21	  const safeY = ctx.height * 0.05;
    22	  const safeW = ctx.width * 0.9;
    23	  const safeH = ctx.height * 0.9;
    24	  const value = Math.max(0, Math.min(100, props.value));
    25	  const trackW = safeW * 0.8;
    26	  const trackH = 22 * u;
    27	  const padX = 40 * u;
    28	  const font = { family: "Montserrat", size: 40 * u, weight: 800 };
    29	  const plateW = trackW + 2 * padX;
    30	  const plateH = 150 * u;
    31	  const plateX = (ctx.width - plateW) / 2;
    32	  const margin = 40 * u;
    33	  const plateY = props.position === "top" ? safeY + margin
    34	    : props.position === "center" ? (ctx.height - plateH) / 2
    35	    : safeY + safeH - margin - plateH;
    36	  const trackX = plateX + padX;
    37	  const trackY = plateY + plateH - 40 * u - trackH;
    38	  const textY = plateY + 40 * u + font.size * 0.72;
    39	  const fillEnd = Math.max(16, Math.round(D * 0.6));
    40	  const grown = interpolate(frame, [8, fillEnd], [0, 1], { easing: Easing.outCubic, clamp: true });
    41	  const fillW = (trackW * value * grown) / 100;
    42	  const plateIn = interpolate(frame, [0, 10], [0, 1], { clamp: true });
    43	  const wipe = interpolate(frame, [2, 20], [0, 1], { easing: Easing.outCubic, clamp: true });
    44	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    45	  const shine = interpolate(frame, [fillEnd - 6, fillEnd + 24], [-0.3, 1.3], { easing: Easing.inOutSine, clamp: true });
    46	  const shineX = trackX + fillW * shine;
    47	  const percent = `${Math.round(value * grown)}%`;
    48	  const labelMax = trackW - (props.showPercent ? 200 * u : 0);
    49	  const labelSize = Math.min(font.size, fitText(props.label, labelMax, font, { min: 10 * u, max: font.size }));
    50	  return svg(ctx, `
    51	    <defs>
    52	      <clipPath id="wipe"><rect x="${plateX}" y="${plateY}" width="${plateW * wipe}" height="${plateH}"/></clipPath>
    53	      <clipPath id="fill"><rect x="${trackX}" y="${trackY}" width="${fillW}" height="${trackH}" rx="${trackH / 2}"/></clipPath>
    54	      <linearGradient id="shine" x1="0" y1="0" x2="1" y2="0">
    55	        <stop offset="0" stop-color="#ffffff" stop-opacity="0"/>
    56	        <stop offset="0.5" stop-color="#ffffff" stop-opacity="0.55"/>
    57	        <stop offset="1" stop-color="#ffffff" stop-opacity="0"/>
    58	      </linearGradient>
    59	    </defs>
    60	    <g opacity="${out * plateIn}">
    61	      <rect x="${plateX}" y="${plateY}" width="${plateW}" height="${plateH}" rx="${18 * u}" fill="#101014"
    62	            fill-opacity="0.82"/>
    63	      <g clip-path="url(#wipe)">
    64	        <text x="${trackX}" y="${textY}" font-family="Montserrat" font-weight="800" font-size="${labelSize}"
    65	              fill="#ffffff">${escapeXml(props.label)}</text>
    66	        ${props.showPercent ? `<text x="${trackX + trackW}" y="${textY}" text-anchor="end" font-family="IBM Plex Mono"
    67	              font-weight="500" font-size="${font.size}" fill="#d8d8e0">${percent}</text>` : ""}
    68	        <rect x="${trackX}" y="${trackY}" width="${trackW}" height="${trackH}" rx="${trackH / 2}" fill="#ffffff"
    69	              fill-opacity="0.12"/>
    70	        ${fillW > 0.5 ? `<rect x="${trackX}" y="${trackY}" width="${fillW}" height="${trackH}" rx="${trackH / 2}"
    71	              fill="${props.accent}"/>
    72	        <g clip-path="url(#fill)"><rect x="${shineX - 90 * u}" y="${trackY}" width="${180 * u}" height="${trackH}"
    73	              fill="url(#shine)"/></g>` : ""}
    74	      </g>
    75	    </g>`);
    76	}

