=== countdown
     1	// countdown — a bundled template (spec §11 G-44): a timer counting from
     2	// `from` to `to` one step a second (up when `to` is greater), its digits
     3	// pulsing on each tick inside a ring that empties or fills, and a flash at
     4	// the end.
     5	export const meta = {
     6	  name: "Countdown",
     7	  durationInFrames: 330,
     8	};
     9	
    10	export const schema = {
    11	  from:   { type: "number",  default: 10 },
    12	  to:     { type: "number",  default: 0 },
    13	  format: { type: "enum",    default: "m:ss", options: ["seconds", "m:ss", "h:mm:ss"] },
    14	  label:  { type: "string",  default: "Starting in" },
    15	  ring:   { type: "boolean", default: true },
    16	  accent: { type: "color",   default: "#ff5a36" },
    17	};
    18	
    19	function clock(n, format) {
    20	  const sign = n < 0 ? "-" : "";
    21	  const s = Math.abs(n);
    22	  const two = (v) => String(v).padStart(2, "0");
    23	  if (format === "seconds") return sign + s;
    24	  if (format === "h:mm:ss") return `${sign}${Math.floor(s / 3600)}:${two(Math.floor(s / 60) % 60)}:${two(s % 60)}`;
    25	  return `${sign}${Math.floor(s / 60)}:${two(s % 60)}`;
    26	}
    27	
    28	export function render(frame, props, ctx) {
    29	  const u = Math.min(ctx.width, ctx.height) / 1080;
    30	  const D = ctx.durationInFrames;
    31	  const from = Math.round(props.from);
    32	  const to = Math.round(props.to);
    33	  const steps = Math.abs(to - from);
    34	  const t = Math.max(0, ctx.time);
    35	  const ticked = Math.min(steps, Math.floor(t));
    36	  const n = to < from ? from - ticked : from + ticked;
    37	  const done = t >= steps;
    38	  const cx = ctx.width / 2;
    39	  const cy = ctx.height / 2;
    40	  const R = 300 * u;
    41	  const thick = 22 * u;
    42	  const enter = spring({ frame, fps: ctx.fps, stiffness: 140, damping: 15 });
    43	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    44	  const local = t - Math.floor(t);
    45	  const pulse = done && t - steps > 0.3 ? 1 : interpolate(local, [0, 0.3], [1.08, 1], { easing: Easing.outCubic, clamp: true });
    46	  const left = Math.max(0, Math.min(1, 1 - t / Math.max(1, steps)));
    47	  const ringShown = to < from ? left : 1 - left;
    48	  const text = clock(n, props.format);
    49	  const widest = clock(from, props.format).length >= clock(to, props.format).length
    50	    ? clock(from, props.format) : clock(to, props.format);
    51	  const digitSize = fitText(widest.replace(/[0-9]/g, "0"), R * 1.45, { family: "IBM Plex Mono", weight: 500 },
    52	    { min: 12 * u, max: 190 * u });
    53	  const flash = done ? interpolate(t - steps, [0, 0.6], [0.85, 0], { easing: Easing.outCubic, clamp: true }) : 0;
    54	  const labelText = props.label.toUpperCase();
    55	  const labelSize = fitText(labelText, R * 1.3, { family: "Montserrat", weight: 800, letterSpacing: 5 * u },
    56	    { min: 10 * u, max: 34 * u });
    57	  const circumference = 2 * Math.PI * R;
    58	  return svg(ctx, `
    59	    <g opacity="${out * Math.min(1, enter * 1.4)}"
    60	       transform="translate(${cx} ${cy}) scale(${0.85 + 0.15 * enter}) translate(${-cx} ${-cy})">
    61	      <circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="#101014" fill-opacity="0.82"/>
    62	      ${flash > 0 ? `<circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="${props.accent}" fill-opacity="${flash}"/>` : ""}
    63	      ${props.ring ? `
    64	      <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.12" stroke-width="${thick}"/>
    65	      ${ringShown > 0.0005 ? `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${props.accent}"
    66	              stroke-width="${thick}" stroke-linecap="round" stroke-dasharray="${circumference * ringShown} ${circumference}"
    67	              transform="rotate(-90 ${cx} ${cy})"/>` : ""}` : ""}
    68	      <text x="${cx}" y="${cy - digitSize * 0.62}" text-anchor="middle" font-family="Montserrat" font-weight="800"
    69	            font-size="${labelSize}" letter-spacing="${5 * u}" fill="#d8d8e0">${escapeXml(labelText)}</text>
    70	      <g transform="translate(${cx} ${cy + digitSize * 0.12}) scale(${pulse})">
    71	        <text x="0" y="${digitSize * 0.35}" text-anchor="middle" font-family="IBM Plex Mono" font-weight="500"
    72	              font-size="${digitSize}" fill="#ffffff">${escapeXml(text)}</text>
    73	      </g>
    74	    </g>`);
    75	}
=== keyboard-keys
     1	// keyboard-keys — a bundled template (spec §11 G-44): a shortcut such as
     2	// "cmd+shift+4" as keycaps popping in one after another, each pressed in
     3	// turn, with a label under them. Modifier and arrow symbols are drawn as
     4	// vector glyphs, never taken from a font.
     5	export const meta = {
     6	  name: "Keyboard keys",
     7	  durationInFrames: 90,
     8	};
     9	
    10	export const schema = {
    11	  keys:     { type: "string", default: "cmd+shift+4", animate: false },
    12	  label:    { type: "string", default: "Screenshot a selection" },
    13	  theme:    { type: "enum",   default: "light", options: ["light", "dark"] },
    14	  position: { type: "enum",   default: "bottom", options: ["bottom", "center", "top"] },
    15	  accent:   { type: "color",  default: "#ff5a36" },
    16	};
    17	
    18	const GLYPHS = {
    19	  cmd: "command", command: "command", "⌘": "command",
    20	  shift: "shift", "⇧": "shift",
    21	  opt: "option", option: "option", alt: "option", "⌥": "option",
    22	  ctrl: "control", control: "control", "⌃": "control",
    23	  up: "up", down: "down", left: "left", right: "right",
    24	};
    25	
    26	// A glyph centred on (0, 0), `g` across, in `colour`.
    27	function glyph(kind, g, colour) {
    28	  const s = (v) => v * g;
    29	  const line = `fill="none" stroke="${colour}" stroke-width="${0.085 * g}" stroke-linecap="round" stroke-linejoin="round"`;
    30	  if (kind === "command") {
    31	    const a = 0.16;
    32	    const r = 0.15;
    33	    const e = a + r;
    34	    return `<path ${line} d="M ${s(a)} ${s(-e)} L ${s(a)} ${s(e)} M ${s(-a)} ${s(-e)} L ${s(-a)} ${s(e)}
    35	      M ${s(-e)} ${s(a)} L ${s(e)} ${s(a)} M ${s(-e)} ${s(-a)} L ${s(e)} ${s(-a)}
    36	      M ${s(a)} ${s(e)} A ${s(r)} ${s(r)} 0 1 0 ${s(e)} ${s(a)}
    37	      M ${s(-a)} ${s(e)} A ${s(r)} ${s(r)} 0 1 1 ${s(-e)} ${s(a)}
    38	      M ${s(a)} ${s(-e)} A ${s(r)} ${s(r)} 0 1 1 ${s(e)} ${s(-a)}
    39	      M ${s(-a)} ${s(-e)} A ${s(r)} ${s(r)} 0 1 0 ${s(-e)} ${s(-a)}"/>`;
    40	  }
    41	  if (kind === "shift") {
    42	    return `<path ${line} d="M 0 ${s(-0.42)} L ${s(0.42)} ${s(0.02)} L ${s(0.19)} ${s(0.02)} L ${s(0.19)} ${s(0.4)}
    43	      L ${s(-0.19)} ${s(0.4)} L ${s(-0.19)} ${s(0.02)} L ${s(-0.42)} ${s(0.02)} Z"/>`;
    44	  }
    45	  if (kind === "option") {
    46	    return `<path ${line} d="M ${s(-0.42)} ${s(-0.3)} L ${s(-0.14)} ${s(-0.3)} L ${s(0.16)} ${s(0.3)} L ${s(0.42)} ${s(0.3)}
    47	      M ${s(0.08)} ${s(-0.3)} L ${s(0.42)} ${s(-0.3)}"/>`;
    48	  }
    49	  if (kind === "control") {
    50	    return `<path ${line} d="M ${s(-0.32)} ${s(0.12)} L 0 ${s(-0.2)} L ${s(0.32)} ${s(0.12)}"/>`;
    51	  }
    52	  const turn = { up: 0, right: 90, down: 180, left: 270 }[kind];
    53	  return `<path d="M 0 ${s(-0.3)} L ${s(0.3)} ${s(0.22)} L ${s(-0.3)} ${s(0.22)} Z" fill="${colour}"
    54	    stroke="${colour}" stroke-width="${0.06 * g}" stroke-linejoin="round" transform="rotate(${turn})"/>`;
    55	}
    56	
    57	export function render(frame, props, ctx) {
    58	  const u = Math.min(ctx.width, ctx.height) / 1080;
    59	  const D = ctx.durationInFrames;
    60	  const safeW = ctx.width * 0.9;
    61	  const safeY = ctx.height * 0.05;
    62	  const safeH = ctx.height * 0.9;
    63	  const dark = props.theme === "dark";
    64	  const face = dark ? "#2c2c33" : "#f6f6f8";
    65	  const lip = dark ? "#121216" : "#b9b9c4";
    66	  const ink = dark ? "#ffffff" : "#1c1c22";
    67	  const tokens = props.keys.split("+").map((t) => t.trim()).filter((t) => t.length > 0);
    68	  const capH = 130 * u;
    69	  const gap = 22 * u;
    70	  const wordFont = { family: "Montserrat", size: 40 * u, weight: 800 };
    71	  const charFont = { family: "Montserrat", size: 60 * u, weight: 800 };
    72	  const caps = tokens.map((t) => {
    73	    const kind = GLYPHS[t.toLowerCase()];
    74	    if (kind) return { kind, w: capH };
    75	    const text = t.length === 1 ? t.toUpperCase() : t;
    76	    const font = t.length === 1 ? charFont : wordFont;
    77	    return { text, font, w: Math.max(capH, measureText(text, font).width + 70 * u) };
    78	  });
    79	  const rowW = caps.reduce((a, c) => a + c.w, 0) + gap * Math.max(0, caps.length - 1);
    80	  const labelFont = { family: "Montserrat", size: 44 * u, weight: 800 };
    81	  const labelSize = props.label.trim() ? fitText(props.label, safeW - 140 * u, labelFont, { min: 10 * u, max: labelFont.size }) : 0;
    82	  const labelH = labelSize > 0 ? labelSize + 56 * u : 0;
    83	  const fit = Math.min(1, (safeW - 80 * u) / Math.max(1, rowW));
    84	  const groupH = capH * fit + (labelH > 0 ? 30 * u + labelH : 0);
    85	  const margin = 50 * u;
    86	  const top = props.position === "top" ? safeY + margin
    87	    : props.position === "center" ? (ctx.height - groupH) / 2
    88	    : safeY + safeH - margin - groupH;
    89	  const cx = ctx.width / 2;
    90	  const cy = top + groupH / 2;
    91	  const enter = (i) => spring({ frame: frame - i * 5, fps: ctx.fps, stiffness: 200, damping: 13 });
    92	  const pressAt = caps.length * 5 + 14;
    93	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
    94	  const outScale = 1 - 0.1 * out;
    95	
    96	  let row = "";
    97	  let x = cx - (rowW * fit) / 2;
    98	  const lipH = 12 * u * fit;
    99	  caps.forEach((c, i) => {
   100	    const w = c.w * fit;
   101	    const h = capH * fit;
   102	    const s = enter(i);
   103	    const dip = interpolate(frame - pressAt - i * 5, [0, 3, 10], [0, 6 * u * fit, 0], { clamp: true });
   104	    const kx = x + w / 2;
   105	    const ky = top + h / 2;
   106	    const rx = 0.18 * h;
   107	    let mark = "";
   108	    if (c.kind) {
   109	      mark = `<g transform="translate(${kx} ${ky - lipH / 2 + dip})">${glyph(c.kind, h * 0.5, ink)}</g>`;
   110	    } else {
   111	      const size = c.font.size * fit;
   112	      mark = `<text x="${kx}" y="${ky - lipH / 2 + dip + size * 0.36}" text-anchor="middle" font-family="Montserrat"
   113	                    font-weight="800" font-size="${size}" fill="${ink}">${escapeXml(c.text)}</text>`;
   114	    }
   115	    if (s > 0.001) {
   116	      row += `<g transform="translate(${kx} ${ky}) scale(${s}) translate(${-kx} ${-ky})">
   117	        <rect x="${x}" y="${top}" width="${w}" height="${h}" rx="${rx}" fill="${lip}"/>
   118	        <rect x="${x}" y="${top + dip}" width="${w}" height="${h - lipH}" rx="${rx}" fill="${face}"/>
   119	        <rect x="${kx - w * 0.22}" y="${top + h - lipH - 18 * u * fit + dip}" width="${w * 0.44}" height="${5 * u * fit}"
   120	              rx="${2.5 * u * fit}" fill="${props.accent}"/>
   121	        ${mark}</g>`;
   122	    }
   123	    x += w + gap * fit;
   124	  });
   125	
   126	  let label = "";
   127	  if (labelSize > 0) {
   128	    const t = spring({ frame: frame - caps.length * 5 - 4, fps: ctx.fps, damping: 16 });
   129	    const lw = measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width + 64 * u;
   130	    const ly = top + capH * fit + 30 * u + (1 - Math.min(1, t)) * 16 * u;
   131	    label = `<g opacity="${Math.max(0, Math.min(1, t))}">
   132	      <rect x="${cx - lw / 2}" y="${ly}" width="${lw}" height="${labelH}" rx="${labelH / 2}" fill="#101014"
   133	            fill-opacity="0.82"/>
   134	      <text x="${cx}" y="${ly + labelH / 2 + labelSize * 0.36}" text-anchor="middle" font-family="Montserrat"
   135	            font-weight="800" font-size="${labelSize}" fill="#ffffff">${escapeXml(props.label)}</text></g>`;
   136	  }
   137	  return svg(ctx, `
   138	    <g opacity="${1 - out}" transform="translate(${cx} ${cy}) scale(${outScale}) translate(${-cx} ${-cy})">
   139	      ${row}${label}
   140	    </g>`);
   141	}
=== window-frame
     1	// window-frame — a bundled template (spec §11 G-44): a window's chrome to
     2	// sit over a screen recording on the track beneath — a title bar with three
     3	// dots and a title (window) or an address field (browser), and a rounded
     4	// outline. The content area stays transparent.
     5	export const meta = {
     6	  name: "Window frame",
     7	  durationInFrames: 150,
     8	};
     9	
    10	export const schema = {
    11	  style:  { type: "enum",    default: "browser", options: ["browser", "window"] },
    12	  title:  { type: "string",  default: "Frame Job" },
    13	  url:    { type: "string",  default: "example.com" },
    14	  theme:  { type: "enum",    default: "dark", options: ["dark", "light"] },
    15	  scale:  { type: "number",  default: 0.86, min: 0.5, max: 1, step: 0.01 },
    16	  shadow: { type: "boolean", default: true },
    17	  accent: { type: "color",   default: "#ff5a36" },
    18	};
    19	
    20	export function render(frame, props, ctx) {
    21	  const u = Math.min(ctx.width, ctx.height) / 1080;
    22	  const D = ctx.durationInFrames;
    23	  const dark = props.theme !== "light";
    24	  const bar = dark ? "#2a2a31" : "#e9e9ee";
    25	  const edge = dark ? "#4a4a54" : "#c4c4cc";
    26	  const field = dark ? "#1b1b20" : "#ffffff";
    27	  const ink = dark ? "#e8e8ee" : "#2a2a31";
    28	  const faint = dark ? "#8a8a96" : "#8a8a96";
    29	  const scale = Math.max(0.5, Math.min(1, props.scale));
    30	  const safeW = ctx.width * 0.9;
    31	  const safeH = ctx.height * 0.9;
    32	  const w = safeW * scale;
    33	  const h = safeH * scale;
    34	  const x = (ctx.width - w) / 2;
    35	  const y = (ctx.height - h) / 2;
    36	  const r = 12 * u;
    37	  const barH = 64 * u;
    38	  const enter = spring({ frame, fps: ctx.fps, stiffness: 120, damping: 17 });
    39	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    40	  const rise = (1 - enter) * 30 * u;
    41	  const grow = 0.96 + 0.04 * enter;
    42	  const alpha = Math.max(0, Math.min(1, enter * 1.6)) * out;
    43	  const cx = ctx.width / 2;
    44	  const cy = ctx.height / 2;
    45	  // The shadow is kept inside title-safe: it is only as wide as the margin around the window allows.
    46	  const margin = Math.min((safeW - w) / 2, (safeH - h) / 2);
    47	  const blur = Math.min(26 * u, margin / 2.2);
    48	
    49	  let dots = "";
    50	  ["#ff5f57", "#febc2e", "#28c840"].forEach((colour, i) => {
    51	    const s = spring({ frame: frame - 8 - i * 4, fps: ctx.fps, stiffness: 260, damping: 12 });
    52	    if (s > 0.001) {
    53	      dots += `<circle cx="${x + 32 * u + i * 26 * u}" cy="${y + barH / 2}" r="${8 * u * s}" fill="${colour}" fill-opacity="${alpha}"/>`;
    54	    }
    55	  });
    56	  const uiFont = { family: "Source Sans 3", size: 26 * u, weight: 600 };
    57	  let middle = "";
    58	  const left = x + 130 * u;
    59	  const room = w - 2 * 130 * u;
