     1	// step-badge — a bundled template (spec §11 G-44): a numbered accent circle
     2	// popping in at a corner, with a label panel wiping out from behind it.
     3	export const meta = {
     4	  name: "Step badge",
     5	  durationInFrames: 90,
     6	};
     7	
     8	export const schema = {
     9	  number:   { type: "number", default: 1, min: 0, max: 99, step: 1, animate: false },
    10	  label:    { type: "string", default: "Open the export sheet" },
    11	  position: { type: "enum",   default: "top-left", options: ["top-left", "top-right", "bottom-left", "bottom-right"] },
    12	  accent:   { type: "color",  default: "#ff5a36" },
    13	};
    14	
    15	export function render(frame, props, ctx) {
    16	  const u = Math.min(ctx.width, ctx.height) / 1080;
    17	  const D = ctx.durationInFrames;
    18	  const safeX = ctx.width * 0.05;
    19	  const safeY = ctx.height * 0.05;
    20	  const safeW = ctx.width * 0.9;
    21	  const safeH = ctx.height * 0.9;
    22	  const R = 60 * u;
    23	  const margin = 40 * u;
    24	  const right = props.position.endsWith("right");
    25	  const bottom = props.position.startsWith("bottom");
    26	  const cx = right ? safeX + safeW - margin - R : safeX + margin + R;
    27	  const cy = bottom ? safeY + safeH - margin - R : safeY + margin + R;
    28	  const n = String(Math.max(0, Math.min(99, Math.round(props.number))));
    29	  const numberSize = n.length > 1 ? 58 * u : 68 * u;
    30	  const panelH = 88 * u;
    31	  const font = { family: "Montserrat", size: 42 * u, weight: 800 };
    32	  const maxText = safeW - 2 * margin - 2 * R - 90 * u;
    33	  const size = props.label ? Math.min(font.size, fitText(props.label, maxText, font, { min: 10 * u, max: font.size })) : font.size;
    34	  const textW = props.label ? measureText(props.label, { family: "Montserrat", size, weight: 800 }).width : 0;
    35	  const panelW = R + 34 * u + textW + 40 * u;
    36	  const pop = spring({ frame, fps: ctx.fps, stiffness: 190, damping: 10 });
    37	  const open = interpolate(frame, [8, 26], [0, 1], { easing: Easing.outCubic, clamp: true });
    38	  const close = interpolate(frame, [D - 15, D - 8], [0, 1], { easing: Easing.inCubic, clamp: true });
    39	  const shrink = interpolate(frame, [D - 8, D - 1], [1, 0], { easing: Easing.inBack, clamp: true });
    40	  const wipe = Math.max(0, open - close);
    41	  const scale = Math.max(0, pop * shrink);
    42	  const px = right ? cx - panelW : cx;
    43	  const py = cy - panelH / 2;
    44	  const shown = panelW * wipe;
    45	  const clipX = right ? cx - shown : cx;
    46	  const textX = right ? cx - R - 34 * u : cx + R + 34 * u;
    47	  const slide = (1 - wipe) * 30 * u * (right ? 1 : -1);
    48	  const panel = shown > 0.5 && props.label
    49	    ? `<clipPath id="wipe"><rect x="${clipX}" y="${py}" width="${shown}" height="${panelH}" rx="${Math.min(shown / 2, panelH / 2)}"/></clipPath>
    50	      <g clip-path="url(#wipe)">
    51	        <rect x="${px}" y="${py}" width="${panelW}" height="${panelH}" rx="${panelH / 2}" fill="#101014" fill-opacity="0.82"/>
    52	        <text x="${textX + slide}" y="${cy + size * 0.36}" text-anchor="${right ? "end" : "start"}" font-family="Montserrat"
    53	              font-weight="800" font-size="${size}" fill="#ffffff">${escapeXml(props.label)}</text>
    54	      </g>`
    55	    : "";
    56	  const badge = scale > 0.001
    57	    ? `<g transform="translate(${cx} ${cy}) scale(${scale})">
    58	        <circle cx="0" cy="0" r="${R}" fill="${props.accent}"/>
    59	        <circle cx="0" cy="0" r="${R - 7 * u}" fill="none" stroke="#ffffff" stroke-opacity="0.35" stroke-width="${3 * u}"/>
    60	        <text x="0" y="${numberSize * 0.36}" text-anchor="middle" font-family="Montserrat" font-weight="900"
    61	              font-size="${numberSize}" fill="#ffffff">${n}</text>
    62	      </g>`
    63	    : "";
    64	  return svg(ctx, `${panel}${badge}`);
    65	}

