     1	// keyboard-keys — a bundled template (spec §11 G-44): a shortcut such as
     2	// "cmd+shift+4" as keycaps popping in one after another, each pressed in
     3	// turn, with a label under them. Modifier and arrow symbols are drawn as
     4	// vector glyphs, never taken from a font.
     5	export const meta = {
     6	  name: "Keyboard keys",
     7	  durationInFrames: 90,
     8	};
     9	
    10	export const schema = {
    11	  keys:     { type: "string", default: "cmd+shift+4", animate: false },
    12	  label:    { type: "string", default: "Screenshot a selection" },
    13	  theme:    { type: "enum",   default: "light", options: ["light", "dark"] },
    14	  position: { type: "enum",   default: "bottom", options: ["bottom", "center", "top"] },
    15	  accent:   { type: "color",  default: "#ff5a36" },
    16	};
    17	
    18	const GLYPHS = {
    19	  cmd: "command", command: "command", "⌘": "command",
    20	  shift: "shift", "⇧": "shift",
    21	  opt: "option", option: "option", alt: "option", "⌥": "option",
    22	  ctrl: "control", control: "control", "⌃": "control",
    23	  up: "up", down: "down", left: "left", right: "right",
    24	};
    25	
    26	// A glyph centred on (0, 0), `g` across, in `colour`.
    27	function glyph(kind, g, colour) {
    28	  const s = (v) => v * g;
    29	  const line = `fill="none" stroke="${colour}" stroke-width="${0.085 * g}" stroke-linecap="round" stroke-linejoin="round"`;
    30	  if (kind === "command") {
    31	    const a = 0.16;
    32	    const r = 0.15;
    33	    const e = a + r;
    34	    return `<path ${line} d="M ${s(a)} ${s(-e)} L ${s(a)} ${s(e)} M ${s(-a)} ${s(-e)} L ${s(-a)} ${s(e)}
    35	      M ${s(-e)} ${s(a)} L ${s(e)} ${s(a)} M ${s(-e)} ${s(-a)} L ${s(e)} ${s(-a)}
    36	      M ${s(a)} ${s(e)} A ${s(r)} ${s(r)} 0 1 0 ${s(e)} ${s(a)}
    37	      M ${s(-a)} ${s(e)} A ${s(r)} ${s(r)} 0 1 1 ${s(-e)} ${s(a)}
    38	      M ${s(a)} ${s(-e)} A ${s(r)} ${s(r)} 0 1 1 ${s(e)} ${s(-a)}
    39	      M ${s(-a)} ${s(-e)} A ${s(r)} ${s(r)} 0 1 0 ${s(-e)} ${s(-a)}"/>`;
    40	  }
    41	  if (kind === "shift") {
    42	    return `<path ${line} d="M 0 ${s(-0.42)} L ${s(0.42)} ${s(0.02)} L ${s(0.19)} ${s(0.02)} L ${s(0.19)} ${s(0.4)}
    43	      L ${s(-0.19)} ${s(0.4)} L ${s(-0.19)} ${s(0.02)} L ${s(-0.42)} ${s(0.02)} Z"/>`;
    44	  }
    45	  if (kind === "option") {
    46	    return `<path ${line} d="M ${s(-0.42)} ${s(-0.3)} L ${s(-0.14)} ${s(-0.3)} L ${s(0.16)} ${s(0.3)} L ${s(0.42)} ${s(0.3)}
    47	      M ${s(0.08)} ${s(-0.3)} L ${s(0.42)} ${s(-0.3)}"/>`;
    48	  }
    49	  if (kind === "control") {
    50	    return `<path ${line} d="M ${s(-0.32)} ${s(0.12)} L 0 ${s(-0.2)} L ${s(0.32)} ${s(0.12)}"/>`;
    51	  }
    52	  const turn = { up: 0, right: 90, down: 180, left: 270 }[kind];
    53	  return `<path d="M 0 ${s(-0.3)} L ${s(0.3)} ${s(0.22)} L ${s(-0.3)} ${s(0.22)} Z" fill="${colour}"
    54	    stroke="${colour}" stroke-width="${0.06 * g}" stroke-linejoin="round" transform="rotate(${turn})"/>`;
    55	}
    56	
    57	export function render(frame, props, ctx) {
    58	  const u = Math.min(ctx.width, ctx.height) / 1080;
    59	  const D = ctx.durationInFrames;
    60	  const safeW = ctx.width * 0.9;
    61	  const safeY = ctx.height * 0.05;
    62	  const safeH = ctx.height * 0.9;
    63	  const dark = props.theme === "dark";
    64	  const face = dark ? "#2c2c33" : "#f6f6f8";
    65	  const lip = dark ? "#121216" : "#b9b9c4";
    66	  const ink = dark ? "#ffffff" : "#1c1c22";
