    80	  const labelFont = { family: "Montserrat", size: 44 * u, weight: 800 };
    81	  const labelSize = props.label.trim() ? fitText(props.label, safeW - 140 * u, labelFont, { min: 10 * u, max: labelFont.size }) : 0;
