    86	  const top = props.position === "top" ? safeY + margin
    87	    : props.position === "center" ? (ctx.height - groupH) / 2
    88	    : safeY + safeH - margin - groupH;
    89	  const cx = ctx.width / 2;
    90	  const cy = top + groupH / 2;
    91	  const enter = (i) => spring({ frame: frame - i * 5, fps: ctx.fps, stiffness: 200, damping: 13 });
    92	  const pressAt = caps.length * 5 + 14;
    93	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
    94	  const outScale = 1 - 0.1 * out;
    95	
    96	  let row = "";
    97	  let x = cx - (rowW * fit) / 2;
    98	  const lipH = 12 * u * fit;
    99	  caps.forEach((c, i) => {
   100	    const w = c.w * fit;
   101	    const h = capH * fit;
   102	    const s = enter(i);
   103	    const dip = interpolate(frame - pressAt - i * 5, [0, 3, 10], [0, 6 * u * fit, 0], { clamp: true });
