   122	    }
   123	    x += w + gap * fit;
   124	  });
   125	
   126	  let label = "";
   127	  if (labelSize > 0) {
   128	    const t = spring({ frame: frame - caps.length * 5 - 4, fps: ctx.fps, damping: 16 });
   129	    const lw = measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width + 64 * u;
   130	    const ly = top + capH * fit + 30 * u + (1 - Math.min(1, t)) * 16 * u;
   131	    label = `<g opacity="${Math.max(0, Math.min(1, t))}">
