   133	            fill-opacity="0.82"/>
   134	      <text x="${cx}" y="${ly + labelH / 2 + labelSize * 0.36}" text-anchor="middle" font-family="Montserrat"
   135	            font-weight="800" font-size="${labelSize}" fill="#ffffff">${escapeXml(props.label)}</text></g>`;
   136	  }
   137	  return svg(ctx, `
   138	    <g opacity="${1 - out}" transform="translate(${cx} ${cy}) scale(${outScale}) translate(${-cx} ${-cy})">
   139	      ${row}${label}
   140	    </g>`);
   141	}
