=== arrow-highlight
     1	// arrow-highlight — a bundled template (spec §11 G-44): a rounded box drawn
     2	// on around a spot and an arrow growing toward it from the side nearer the
     3	// frame's centre, with a label at the arrow's tail.
     4	export const meta = {
     5	  name: "Arrow highlight",
     6	  durationInFrames: 90,
     7	};
     8	
     9	export const schema = {
    10	  x:         { type: "number", default: 0.62, min: 0, max: 1, step: 0.01 },
    11	  y:         { type: "number", default: 0.42, min: 0, max: 1, step: 0.01 },
    12	  boxWidth:  { type: "number", default: 0.22, min: 0.02, max: 0.8, step: 0.01 },
    13	  boxHeight: { type: "number", default: 0.14, min: 0.02, max: 0.8, step: 0.01 },
    14	  shape:     { type: "enum",   default: "box+arrow", options: ["box+arrow", "box", "arrow"] },
    15	  label:     { type: "string", default: "Look here" },
    16	  accent:    { type: "color",  default: "#ffd60a" },
    17	};
    18	
    19	const clamp = (v, lo, hi) => Math.max(lo, Math.min(Math.max(lo, hi), v));
    20	
    21	export function render(frame, props, ctx) {
    22	  const u = Math.min(ctx.width, ctx.height) / 1080;
    23	  const D = ctx.durationInFrames;
    24	  const W = ctx.width;
    25	  const H = ctx.height;
    26	  const inset = 30 * u;
    27	  const x0 = W * 0.05 + inset;
    28	  const y0 = H * 0.05 + inset;
    29	  const x1 = W * 0.95 - inset;
    30	  const y1 = H * 0.95 - inset;
    31	  const showBox = props.shape !== "arrow";
    32	  const showArrow = props.shape !== "box";
    33	  const bw = showBox ? Math.min(x1 - x0, Math.max(0.02, props.boxWidth) * W) : 0;
    34	  const bh = showBox ? Math.min(y1 - y0, Math.max(0.02, props.boxHeight) * H) : 0;
    35	  const cx = clamp(props.x * W, x0 + bw / 2, x1 - bw / 2);
    36	  const cy = clamp(props.y * H, y0 + bh / 2, y1 - bh / 2);
    37	  const stroke = 8 * u;
    38	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    39	  const font = { family: "Montserrat", size: 56 * u, weight: 800 };
    40	  const labelSize = props.label ? fitText(props.label, x1 - x0, font, { min: 10 * u, max: font.size }) : 0;
    41	  const labelW = props.label ? measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width : 0;
    42	
    43	  let box = "";
    44	  if (showBox) {
    45	    const r = Math.min(14 * u, bw / 2, bh / 2);
    46	    const bx = cx - bw / 2;
    47	    const by = cy - bh / 2;
    48	    const d = `M ${bx + r} ${by} H ${bx + bw - r} A ${r} ${r} 0 0 1 ${bx + bw} ${by + r} V ${by + bh - r}
    49	      A ${r} ${r} 0 0 1 ${bx + bw - r} ${by + bh} H ${bx + r} A ${r} ${r} 0 0 1 ${bx} ${by + bh - r} V ${by + r}
    50	      A ${r} ${r} 0 0 1 ${bx + r} ${by} Z`;
    51	    const drawn = interpolate(frame, [0, 24], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    52	    const dash = evolvePath(drawn, d);
    53	    box = drawn > 0 ? `<path d="${d}" fill="none" stroke="${props.accent}" stroke-width="${stroke}"
    54	      stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${dash.strokeDasharray}"
    55	      stroke-dashoffset="${dash.strokeDashoffset}" stroke-opacity="${out}"/>` : "";
    56	  }
    57	
    58	  // The tail lies toward the frame's centre (down and left when the spot is the centre).
    59	  let dx = W / 2 - cx;
    60	  let dy = H / 2 - cy;
    61	  const len = Math.hypot(dx, dy);
    62	  if (len < 1) {
    63	    dx = -1;
    64	    dy = 1;
    65	  }
    66	  const norm = Math.hypot(dx, dy);
    67	  dx /= norm;
    68	  dy /= norm;
    69	  // Where the ray from the centre leaves the box (or the spot itself), plus a gap.
    70	  const exit = showBox ? Math.min(bw / 2 / Math.max(1e-6, Math.abs(dx)), bh / 2 / Math.max(1e-6, Math.abs(dy))) : 0;
    71	  const gapped = exit + 22 * u;
    72	  const headX = cx + dx * gapped;
    73	  const headY = cy + dy * gapped;
    74	  const reach = 240 * u;
    75	  const below = dy >= 0;
    76	  const labelRoom = props.label ? labelSize * 1.3 : 0;
    77	  const tailX = clamp(headX + dx * reach, x0 + 10 * u, x1 - 10 * u);
    78	  const tailY = clamp(headY + dy * reach, y0 + (below ? 0 : labelRoom), y1 - (below ? labelRoom : 0));
    79	  const grow = interpolate(frame, [18, 36], [0, 1], { easing: Easing.outBack, clamp: true });
    80	  let arrow = "";
    81	  if (showArrow && grow > 0) {
    82	    const hx = tailX + (headX - tailX) * grow;
    83	    const hy = tailY + (headY - tailY) * grow;
    84	    const angle = Math.atan2(headY - tailY, headX - tailX);
    85	    const head = 34 * u;
    86	    const p1 = `${hx - head * Math.cos(angle - 0.5)},${hy - head * Math.sin(angle - 0.5)}`;
    87	    const p2 = `${hx - head * Math.cos(angle + 0.5)},${hy - head * Math.sin(angle + 0.5)}`;
    88	    const back = 0.8 * head;
    89	    arrow = `<line x1="${tailX}" y1="${tailY}" x2="${hx - back * Math.cos(angle) * 0.5}" y2="${hy - back * Math.sin(angle) * 0.5}"
    90	                   stroke="${props.accent}" stroke-opacity="${out}" stroke-width="${stroke}" stroke-linecap="round"/>
    91	      <polygon points="${hx},${hy} ${p1} ${p2}" fill="${props.accent}" fill-opacity="${out}" stroke="${props.accent}"
    92	               stroke-opacity="${out}" stroke-width="${3 * u}" stroke-linejoin="round"/>`;
    93	  }
    94	  let label = "";
    95	  if (props.label) {
    96	    const t = spring({ frame: frame - (showArrow ? 30 : 20), fps: ctx.fps, damping: 15 });
    97	    let lx;
    98	    let ly;
    99	    if (showArrow) {
   100	      lx = tailX;
   101	      ly = below ? tailY + labelSize * 1.15 : tailY - labelSize * 0.45;
   102	    } else {
   103	      lx = cx;
   104	      ly = cy + bh / 2 + 20 * u + labelSize;
   105	      if (ly > y1) ly = cy - bh / 2 - 26 * u;
   106	    }
   107	    lx = clamp(lx, x0 + labelW / 2, x1 - labelW / 2);
   108	    label = `<text x="${lx}" y="${ly}" text-anchor="middle" font-family="Montserrat" font-weight="800"
   109	          font-size="${labelSize}" fill="#ffffff" stroke="#0b0b10" stroke-width="${9 * u}" stroke-linejoin="round" paint-order="stroke"
   110	          fill-opacity="${Math.max(0, Math.min(1, t)) * out}" stroke-opacity="${Math.max(0, Math.min(1, t)) * out * 0.85}"
   111	          >${escapeXml(props.label)}</text>`;
   112	  }
   113	  return svg(ctx, `${box}${arrow}${label}`);
   114	}
=== chapter-card
     1	// chapter-card — a bundled template (spec §11 G-44): a full card with a
     2	// large outlined chapter numeral, a kicker whose spacing settles, an accent
     3	// rule drawing across and the title revealed upward.
     4	export const meta = {
     5	  name: "Chapter card",
     6	  durationInFrames: 120,
     7	};
     8	
     9	export const schema = {
    10	  number:     { type: "number", default: 1, min: 0, max: 99, step: 1, animate: false },
    11	  kicker:     { type: "string", default: "CHAPTER" },
    12	  title:      { type: "string", default: "Getting started" },
    13	  background: { type: "color",  default: "#0b0b10" },
    14	  accent:     { type: "color",  default: "#ff5a36" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const D = ctx.durationInFrames;
    20	  const safeX = ctx.width * 0.05;
    21	  const safeW = ctx.width * 0.9;
    22	  const pad = 70 * u;
    23	  const left = safeX + pad;
    24	  const width = safeW - 2 * pad;
    25	  const numeral = String(Math.max(0, Math.min(99, Math.round(props.number)))).padStart(2, "0");
    26	  const numSize = 300 * u;
    27	  const numFont = { family: "Montserrat", size: numSize, weight: 900 };
    28	  const numW = measureText(numeral, numFont).width;
    29	  const titleSize = fitText(props.title, width, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 150 * u });
    30	  const kickerSize = 44 * u;
    31	  const blockH = numSize * 0.74 + 60 * u + titleSize * 0.74 + 40 * u;
    32	  const top = (ctx.height - blockH) / 2;
    33	  const numBase = top + numSize * 0.74;
    34	  const ruleY = numBase + 46 * u;
    35	  const titleBase = ruleY + 34 * u + titleSize * 0.74;
    36	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    37	  const lift = interpolate(frame, [D - 15, D - 1], [0, -24 * u], { easing: Easing.inCubic, clamp: true });
    38	  const numIn = interpolate(frame, [0, 22], [0, 1], { easing: Easing.outCubic, clamp: true });
    39	  const numScale = 1.15 - 0.15 * numIn;
    40	  const kickIn = interpolate(frame, [8, 30], [0, 1], { easing: Easing.outCubic, clamp: true });
    41	  const spacing = (22 - 14 * kickIn) * u;
    42	  const rule = interpolate(frame, [14, 38], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    43	  const reveal = interpolate(frame, [22, 46], [0, 1], { easing: Easing.outCubic, clamp: true });
    44	  const kickerX = left + numW + 40 * u;
    45	  const kickerMax = left + width - kickerX;
    46	  const kickerFit = Math.min(kickerSize, fitText(props.kicker, kickerMax,
    47	    { family: "Montserrat", weight: 800, letterSpacing: 22 * u }, { min: 10 * u, max: kickerSize }));
    48	  const ncx = left + numW / 2;
    49	  const ncy = numBase - numSize * 0.37;
    50	  const ruleW = width * rule;
    51	  const rise = (1 - reveal) * titleSize * 1.15;
    52	  return svg(ctx, `
    53	    <defs>
    54	      <clipPath id="title"><rect x="${safeX}" y="${ruleY + 10 * u}" width="${safeW}" height="${titleBase - ruleY - 10 * u + titleSize * 0.26}"/></clipPath>
    55	    </defs>
    56	    <g transform="translate(0 ${lift})">
    57	      <g transform="translate(${ncx} ${ncy}) scale(${numScale}) translate(${-ncx} ${-ncy})">
    58	        <text x="${left}" y="${numBase}" font-family="Montserrat" font-weight="900" font-size="${numSize}" fill="none"
    59	              stroke="${props.accent}" stroke-width="${4 * u}" stroke-opacity="${numIn * out}">${numeral}</text>
    60	      </g>
    61	      <text x="${kickerX}" y="${numBase - numSize * 0.37 + kickerFit * 0.36}" font-family="Montserrat" font-weight="800"
    62	            font-size="${kickerFit}" letter-spacing="${spacing}" fill="#d8d8e0"
    63	            fill-opacity="${kickIn * out}">${escapeXml(props.kicker)}</text>
    64	      ${ruleW > 0.5 ? `<rect x="${left}" y="${ruleY}" width="${ruleW}" height="${6 * u}" fill="${props.accent}"
    65	            fill-opacity="${out}"/>` : ""}
    66	      <g clip-path="url(#title)">
    67	        <text x="${left}" y="${titleBase + rise}" font-family="Montserrat" font-weight="900" font-size="${titleSize}"
    68	              fill="#ffffff" fill-opacity="${out}">${escapeXml(props.title)}</text>
    69	      </g>
    70	    </g>`, { background: props.background });
    71	}
=== quote-card
     1	// quote-card — a bundled template (spec §11 G-44): a full card with an
     2	// accent opening quote mark drawn as a vector shape, the quote's lines
     3	// fading up in turn, and a rule and attribution sliding in.
     4	export const meta = {
     5	  name: "Quote card",
     6	  durationInFrames: 150,
     7	};
     8	
     9	export const schema = {
    10	  quote:       { type: "string", default: "The best way to get started is to quit talking and begin doing.", multiline: true },
    11	  attribution: { type: "string", default: "Walt Disney" },
    12	  background:  { type: "color",  default: "#101014" },
    13	  accent:      { type: "color",  default: "#ffd60a" },
    14	};
    15	
    16	// One “6”-shaped quote half: a ball with a tail rising to the upper right, `s` tall.
    17	function mark(x, y, s) {
    18	  const r = s * 0.3;
    19	  const cx = x + r;
    20	  const cy = y + s - r;
    21	  return `<circle cx="${cx}" cy="${cy}" r="${r}"/>
    22	    <path d="M ${cx - r} ${cy} C ${cx - r} ${cy - r * 2.2} ${cx + r * 0.2} ${y + s * 0.08} ${cx + r * 1.25} ${y}
    23	             L ${cx + r * 1.25} ${y + s * 0.18} C ${cx + r * 0.25} ${y + s * 0.3} ${cx - r * 0.15} ${cy - r * 1.3} ${cx + r * 0.2} ${cy - r * 0.95} Z"/>`;
    24	}
    25	
    26	export function render(frame, props, ctx) {
    27	  const u = Math.min(ctx.width, ctx.height) / 1080;
    28	  const D = ctx.durationInFrames;
    29	  const safeY = ctx.height * 0.05;
    30	  const safeW = ctx.width * 0.9;
    31	  const safeH = ctx.height * 0.9;
    32	  const textW = safeW * 0.8;
    33	  const left = (ctx.width - textW) / 2;
    34	  const markH = 110 * u;
    35	  const attrSize = 40 * u;
    36	  const reserved = markH + 50 * u + 100 * u + attrSize + 2 * 60 * u;
    37	  let size = 84 * u;
    38	  let lines = [];
    39	  for (; size > 28 * u; size -= 4 * u) {
    40	    lines = wrapText(props.quote, textW, { family: "Montserrat", size, weight: 800 });
    41	    if (lines.length * size * 1.25 <= safeH - reserved) break;
    42	  }
    43	  if (size <= 28 * u) {
    44	    size = 28 * u;
    45	    lines = wrapText(props.quote, textW, { family: "Montserrat", size, weight: 800 });
    46	  }
    47	  const lineH = size * 1.25;
    48	  const blockH = markH + 50 * u + lines.length * lineH + 100 * u + attrSize;
    49	  const top = safeY + Math.max(60 * u, (safeH - blockH) / 2);
    50	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    51	  const markIn = spring({ frame, fps: ctx.fps, stiffness: 160, damping: 12 });
    52	  const mx = left;
    53	  const my = top;
    54	  const mcx = mx + markH * 0.6;
    55	  const mcy = my + markH / 2;
    56	  let body = "";
    57	  lines.forEach((line, i) => {
    58	    const t = interpolate(frame, [10 + i * 6, 28 + i * 6], [0, 1], { easing: Easing.outCubic, clamp: true });
    59	    const y = top + markH + 50 * u + size * 0.9 + i * lineH + (1 - t) * 24 * u;
    60	    body += `<text x="${left}" y="${y}" font-family="Montserrat" font-weight="800" font-size="${size}" fill="#ffffff"
    61	                   fill-opacity="${t * out}">${escapeXml(line)}</text>`;
    62	  });
    63	  const endLines = 28 + lines.length * 6;
    64	  const attrIn = interpolate(frame, [endLines - 6, endLines + 14], [0, 1], { easing: Easing.outCubic, clamp: true });
    65	  const attrY = top + markH + 50 * u + lines.length * lineH + 60 * u + 40 * u;
    66	  const slide = (1 - attrIn) * -40 * u;
    67	  const attrText = props.attribution.trim() ? `— ${props.attribution}` : "";
    68	  const attrFit = attrText ? Math.min(attrSize, fitText(attrText, textW,
    69	    { family: "Montserrat", weight: 800 }, { min: 10 * u, max: attrSize })) : attrSize;
    70	  return svg(ctx, `
    71	    ${markIn > 0.001 ? `<g fill="${props.accent}" fill-opacity="${out}"
    72	       transform="translate(${mcx} ${mcy}) scale(${markIn}) translate(${-mcx} ${-mcy})">
    73	      ${mark(mx, my, markH)}${mark(mx + markH * 0.72, my, markH)}
    74	    </g>` : ""}
    75	    ${body}
    76	    ${attrIn > 0 ? `<rect x="${left + slide}" y="${attrY - attrSize - 34 * u}" width="${80 * u}" height="${6 * u}"
    77	          fill="${props.accent}" fill-opacity="${attrIn * out}"/>
    78	    <text x="${left + slide}" y="${attrY}" font-family="Montserrat" font-weight="800"
    79	          font-size="${attrFit}" fill="#d8d8e0" fill-opacity="${attrIn * out}">${escapeXml(attrText)}</text>` : ""}`,
    80	    { background: props.background });
    81	}
