     1	// news-ticker — a bundled template (spec §11 G-44): a band along the foot of
     2	// title-safe with an accent headline box and items crawling right to left,
     3	// separated by accent bullets.
     4	export const meta = {
     5	  name: "News ticker",
     6	  durationInFrames: 300,
     7	};
     8	
     9	export const schema = {
    10	  headline:   { type: "string", default: "BREAKING" },
    11	  items:      { type: "string", default: "Frame Job adds 17 graphic templates | Charts, timers and social pop-ups | Every one drawn by code", animate: false },
    12	  speed:      { type: "number", default: 160, min: 40, max: 600, step: 10 },
    13	  background: { type: "color",  default: "#101014" },
    14	  accent:     { type: "color",  default: "#e5322d" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const D = ctx.durationInFrames;
    20	  const x0 = ctx.width * 0.05;
    21	  const bandW = ctx.width * 0.9;
    22	  const bandH = 84 * u;
    23	  const y = ctx.height * 0.95 - bandH;
    24	  const headFont = { family: "Montserrat", size: 38 * u, weight: 900 };
    25	  const itemFont = { family: "Montserrat", size: 36 * u, weight: 800 };
    26	  const headSize = props.headline ? Math.min(headFont.size, fitText(props.headline, bandW * 0.4,
    27	    { family: "Montserrat", weight: 900, letterSpacing: 2 * u }, { min: 10 * u, max: headFont.size })) : 0;
    28	  const headW = props.headline
    29	    ? measureText(props.headline, { family: "Montserrat", size: headSize, weight: 900, letterSpacing: 2 * u }).width + 56 * u
    30	    : 0;
    31	  const wipeIn = interpolate(frame, [0, 16], [0, 1], { easing: Easing.outCubic, clamp: true });
    32	  const wipeOut = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
    33	  const clipLeft = x0 + bandW * wipeOut;
    34	  const clipRight = x0 + bandW * wipeIn;
    35	  const pop = spring({ frame: frame - 8, fps: ctx.fps, stiffness: 200, damping: 13 });
    36	  const items = props.items.split("|").map((s) => s.trim()).filter((s) => s.length > 0);
    37	  const bulletGap = 34 * u;
    38	  const bulletR = 7 * u;
    39	  const widths = items.map((s) => measureText(s, itemFont).width);
    40	  const cycle = widths.reduce((a, w) => a + w + 2 * bulletGap, 0);
    41	  const crawlLeft = x0 + headW;
    42	  const crawlRight = x0 + bandW;
    43	  const baseline = y + bandH / 2 + itemFont.size * 0.36;
    44	  let crawl = "";
    45	  if (items.length > 0 && cycle > 0) {
    46	    const offset = props.speed * u * Math.max(0, ctx.time);
    47	    let start = crawlRight - offset;
    48	    if (start < crawlLeft - cycle) start += Math.floor((crawlLeft - start) / cycle - 1) * cycle;
    49	    for (let k = 0; start + k * cycle < crawlRight; k++) {
    50	      let x = start + k * cycle;
    51	      items.forEach((s, i) => {
    52	        if (x < crawlRight && x + widths[i] > crawlLeft) {
    53	          crawl += `<text x="${x}" y="${baseline}" font-family="Montserrat" font-weight="800" font-size="${itemFont.size}"
    54	                          fill="#ffffff">${escapeXml(s)}</text>`;
    55	        }
    56	        x += widths[i] + bulletGap;
    57	        crawl += `<circle cx="${x}" cy="${y + bandH / 2}" r="${bulletR}" fill="${props.accent}"/>`;
    58	        x += bulletGap;
    59	      });
    60	    }
    61	  }
    62	  const hx = x0 + headW / 2;
    63	  const hy = y + bandH / 2;
    64	  const headBox = props.headline && pop > 0.001
    65	    ? `<g transform="translate(${hx} ${hy}) scale(${Math.min(1.06, pop)}) translate(${-hx} ${-hy})">
    66	        <rect x="${x0}" y="${y}" width="${headW}" height="${bandH}" fill="${props.accent}"/>
    67	        <text x="${hx}" y="${hy + headSize * 0.36}" text-anchor="middle" font-family="Montserrat" font-weight="900"
    68	              font-size="${headSize}" letter-spacing="${2 * u}" fill="#ffffff">${escapeXml(props.headline)}</text>
    69	      </g>`
    70	    : "";
    71	  return svg(ctx, `
    72	    <defs>
    73	      <clipPath id="band"><rect x="${clipLeft}" y="${y}" width="${Math.max(0, clipRight - clipLeft)}" height="${bandH}"/></clipPath>
    74	      <clipPath id="crawl"><rect x="${crawlLeft}" y="${y}" width="${Math.max(0, crawlRight - crawlLeft)}" height="${bandH}"/></clipPath>
    75	    </defs>
    76	    ${clipRight - clipLeft > 0.5 ? `<g clip-path="url(#band)">
    77	      <rect x="${x0}" y="${y}" width="${bandW}" height="${bandH}" fill="${props.background}" fill-opacity="0.92"/>
    78	      <rect x="${x0}" y="${y}" width="${bandW}" height="${4 * u}" fill="${props.accent}"/>
    79	      <g clip-path="url(#crawl)">${crawl}</g>
    80	      ${headBox}
    81	    </g>` : ""}`);
    82	}
=== logo-reveal
     1	// logo-reveal — a bundled template (spec §11 G-44): a full card on which an
     2	// accent bar sweeps across the centre, wiping in a logo image (or, with none,
     3	// a text mark) that settles to size; the bar becomes a rule and a tagline fades up.
     4	export const meta = {
     5	  name: "Logo reveal",
     6	  durationInFrames: 120,
     7	};
     8	
     9	export const schema = {
    10	  logo:       { type: "asset",  default: null, kind: "image" },
    11	  mark:       { type: "string", default: "FRAME JOB" },
    12	  tagline:    { type: "string", default: "Edit at the speed of thought" },
    13	  background: { type: "color",  default: "#0b0b10" },
    14	  accent:     { type: "color",  default: "#ff5a36" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const D = ctx.durationInFrames;
    20	  const safeW = ctx.width * 0.9;
    21	  const safeH = ctx.height * 0.9;
    22	  const cx = ctx.width / 2;
    23	  const cy = ctx.height / 2;
    24	  let markW;
    25	  let markH;
    26	  let content;
    27	  const markSize = fitText(props.mark, safeW * 0.8, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 200 * u });
    28	  if (props.logo) {
    29	    markW = safeW * 0.5;
    30	    markH = Math.min(safeH * 0.32, markW);
    31	    content = `<image href="${asset(props.logo)}" x="${cx - markW / 2}" y="${cy - markH / 2}" width="${markW}"
    32	                      height="${markH}" preserveAspectRatio="xMidYMid meet"/>`;
    33	  } else {
    34	    markW = measureText(props.mark, { family: "Montserrat", size: markSize, weight: 900 }).width;
    35	    markH = markSize * 0.74;
    36	    content = `<text x="${cx}" y="${cy + markH / 2}" text-anchor="middle" font-family="Montserrat" font-weight="900"
    37	                     font-size="${markSize}" fill="#ffffff">${escapeXml(props.mark)}</text>`;
    38	  }
    39	  const barH = markH + 80 * u;
    40	  const barW = 16 * u;
    41	  const from = cx - markW / 2 - 50 * u;
    42	  const to = cx + markW / 2 + 50 * u;
    43	  const sweep = interpolate(frame, [4, 34], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    44	  const barX = from + (to - from) * sweep;
    45	  // After its sweep the bar settles into a short rule under the mark.
    46	  const morph = interpolate(frame, [36, 54], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    47	  const ruleY = cy + markH / 2 + 34 * u;
    48	  const bw = barW + (150 * u - barW) * morph;
    49	  const bh = barH + (6 * u - barH) * morph;
    50	  const bcx = barX + (cx - barX) * morph;
    51	  const bcy = cy + (ruleY - cy) * morph;
    52	  const settle = interpolate(frame, [4, 54], [1.06, 1], { easing: Easing.outCubic, clamp: true });
    53	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
    54	  const scale = settle + 0.04 * out;
    55	  const alpha = 1 - out;
    56	  const tagIn = interpolate(frame, [46, 68], [0, 1], { easing: Easing.outCubic, clamp: true });
    57	  const tagSize = props.tagline ? Math.min(44 * u, fitText(props.tagline, safeW * 0.8,
    58	    { family: "Montserrat", weight: 800 }, { min: 10 * u, max: 44 * u })) : 0;
    59	  const tagY = ruleY + 40 * u + tagSize * 0.9 + (1 - tagIn) * 20 * u;
    60	  const revealW = Math.max(0, barX - (from - 10 * u));
    61	  return svg(ctx, `
    62	    <defs>
    63	      <clipPath id="wipe"><rect x="${from - 10 * u}" y="${cy - barH / 2}" width="${revealW}" height="${barH}"/></clipPath>
    64	    </defs>
    65	    <g opacity="${alpha}" transform="translate(${cx} ${cy}) scale(${scale}) translate(${-cx} ${-cy})">
    66	      ${sweep >= 1 ? content : revealW > 0.5 ? `<g clip-path="url(#wipe)">${content}</g>` : ""}
    67	      ${props.tagline ? `<text x="${cx}" y="${tagY}" text-anchor="middle" font-family="Montserrat" font-weight="800"
    68	            font-size="${tagSize}" fill="#d8d8e0" fill-opacity="${tagIn}">${escapeXml(props.tagline)}</text>` : ""}
    69	      ${sweep > 0 ? `<rect x="${bcx - bw / 2}" y="${bcy - bh / 2}" width="${bw}" height="${bh}" fill="${props.accent}"/>` : ""}
    70	    </g>`, { background: props.background });
    71	}

