     1	// arrow-highlight — a bundled template (spec §11 G-44): a rounded box drawn
     2	// on around a spot and an arrow growing toward it from the side nearer the
     3	// frame's centre, with a label at the arrow's tail.
     4	export const meta = {
     5	  name: "Arrow highlight",
     6	  durationInFrames: 90,
     7	};
     8	
     9	export const schema = {
    10	  x:         { type: "number", default: 0.62, min: 0, max: 1, step: 0.01 },
    11	  y:         { type: "number", default: 0.42, min: 0, max: 1, step: 0.01 },
    12	  boxWidth:  { type: "number", default: 0.22, min: 0.02, max: 0.8, step: 0.01 },
    13	  boxHeight: { type: "number", default: 0.14, min: 0.02, max: 0.8, step: 0.01 },
    14	  shape:     { type: "enum",   default: "box+arrow", options: ["box+arrow", "box", "arrow"] },
    15	  label:     { type: "string", default: "Look here" },
    16	  accent:    { type: "color",  default: "#ffd60a" },
    17	};
    18	
    19	const clamp = (v, lo, hi) => Math.max(lo, Math.min(Math.max(lo, hi), v));
    20	
    21	export function render(frame, props, ctx) {
    22	  const u = Math.min(ctx.width, ctx.height) / 1080;
    23	  const D = ctx.durationInFrames;
    24	  const W = ctx.width;
    25	  const H = ctx.height;
    26	  const inset = 30 * u;
    27	  const x0 = W * 0.05 + inset;
    28	  const y0 = H * 0.05 + inset;
    29	  const x1 = W * 0.95 - inset;
    30	  const y1 = H * 0.95 - inset;
    31	  const showBox = props.shape !== "arrow";
    32	  const showArrow = props.shape !== "box";
    33	  const bw = showBox ? Math.min(x1 - x0, Math.max(0.02, props.boxWidth) * W) : 0;
    34	  const bh = showBox ? Math.min(y1 - y0, Math.max(0.02, props.boxHeight) * H) : 0;
    35	  const cx = clamp(props.x * W, x0 + bw / 2, x1 - bw / 2);
    36	  const cy = clamp(props.y * H, y0 + bh / 2, y1 - bh / 2);
    37	  const stroke = 8 * u;
    38	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    39	  const font = { family: "Montserrat", size: 56 * u, weight: 800 };
    40	  const labelSize = props.label ? fitText(props.label, x1 - x0, font, { min: 10 * u, max: font.size }) : 0;
    41	  const labelW = props.label ? measureText(props.label, { family: "Montserrat", size: labelSize, weight: 800 }).width : 0;
    42	
    43	  let box = "";
    44	  if (showBox) {
    45	    const r = Math.min(14 * u, bw / 2, bh / 2);
    46	    const bx = cx - bw / 2;
    47	    const by = cy - bh / 2;
    48	    const d = `M ${bx + r} ${by} H ${bx + bw - r} A ${r} ${r} 0 0 1 ${bx + bw} ${by + r} V ${by + bh - r}
    49	      A ${r} ${r} 0 0 1 ${bx + bw - r} ${by + bh} H ${bx + r} A ${r} ${r} 0 0 1 ${bx} ${by + bh - r} V ${by + r}
    50	      A ${r} ${r} 0 0 1 ${bx + r} ${by} Z`;
    51	    const drawn = interpolate(frame, [0, 24], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    52	    const dash = evolvePath(drawn, d);
    53	    box = drawn > 0 ? `<path d="${d}" fill="none" stroke="${props.accent}" stroke-width="${stroke}"
    54	      stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${dash.strokeDasharray}"
    55	      stroke-dashoffset="${dash.strokeDashoffset}" stroke-opacity="${out}"/>` : "";
    56	  }
    57	
    58	  // The tail lies toward the frame's centre (down and left when the spot is the centre).
    59	  let dx = W / 2 - cx;
    60	  let dy = H / 2 - cy;
    61	  const len = Math.hypot(dx, dy);
    62	  if (len < 1) {
    63	    dx = -1;
    64	    dy = 1;
    65	  }
    66	  const norm = Math.hypot(dx, dy);
    67	  dx /= norm;
    68	  dy /= norm;
    69	  // Where the ray from the centre leaves the box (or the spot itself), plus a gap.
    70	  const exit = showBox ? Math.min(bw / 2 / Math.max(1e-6, Math.abs(dx)), bh / 2 / Math.max(1e-6, Math.abs(dy))) : 0;
    71	  const gapped = exit + 22 * u;
    72	  const headX = cx + dx * gapped;
    73	  const headY = cy + dy * gapped;
    74	  const reach = 240 * u;
    75	  const below = dy >= 0;
    76	  const labelRoom = props.label ? labelSize * 1.3 : 0;
    77	  const tailX = clamp(headX + dx * reach, x0 + 10 * u, x1 - 10 * u);
    78	  const tailY = clamp(headY + dy * reach, y0 + (below ? 0 : labelRoom), y1 - (below ? labelRoom : 0));
    79	  const grow = interpolate(frame, [18, 36], [0, 1], { easing: Easing.outBack, clamp: true });
    80	  let arrow = "";
    81	  if (showArrow && grow > 0) {
    82	    const hx = tailX + (headX - tailX) * grow;
    83	    const hy = tailY + (headY - tailY) * grow;
    84	    const angle = Math.atan2(headY - tailY, headX - tailX);
    85	    const head = 34 * u;
    86	    const p1 = `${hx - head * Math.cos(angle - 0.5)},${hy - head * Math.sin(angle - 0.5)}`;
    87	    const p2 = `${hx - head * Math.cos(angle + 0.5)},${hy - head * Math.sin(angle + 0.5)}`;
    88	    const back = 0.8 * head;
    89	    arrow = `<line x1="${tailX}" y1="${tailY}" x2="${hx - back * Math.cos(angle) * 0.5}" y2="${hy - back * Math.sin(angle) * 0.5}"
    90	                   stroke="${props.accent}" stroke-opacity="${out}" stroke-width="${stroke}" stroke-linecap="round"/>
    91	      <polygon points="${hx},${hy} ${p1} ${p2}" fill="${props.accent}" fill-opacity="${out}" stroke="${props.accent}"
    92	               stroke-opacity="${out}" stroke-width="${3 * u}" stroke-linejoin="round"/>`;
    93	  }
    94	  let label = "";
    95	  if (props.label) {
    96	    const t = spring({ frame: frame - (showArrow ? 30 : 20), fps: ctx.fps, damping: 15 });
    97	    let lx;
    98	    let ly;
    99	    if (showArrow) {
   100	      lx = tailX;
   101	      ly = below ? tailY + labelSize * 1.15 : tailY - labelSize * 0.45;
   102	    } else {
   103	      lx = cx;
   104	      ly = cy + bh / 2 + 20 * u + labelSize;
   105	      if (ly > y1) ly = cy - bh / 2 - 26 * u;
   106	    }
   107	    lx = clamp(lx, x0 + labelW / 2, x1 - labelW / 2);
   108	    label = `<text x="${lx}" y="${ly}" text-anchor="middle" font-family="Montserrat" font-weight="800"
   109	          font-size="${labelSize}" fill="#ffffff" stroke="#0b0b10" stroke-width="${9 * u}" stroke-linejoin="round" paint-order="stroke"
   110	          fill-opacity="${Math.max(0, Math.min(1, t)) * out}" stroke-opacity="${Math.max(0, Math.min(1, t)) * out * 0.85}"
   111	          >${escapeXml(props.label)}</text>`;
   112	  }
   113	  return svg(ctx, `${box}${arrow}${label}`);
   114	}
