     1	// quote-card — a bundled template (spec §11 G-44): a full card with an
     2	// accent opening quote mark drawn as a vector shape, the quote's lines
     3	// fading up in turn, and a rule and attribution sliding in.
     4	export const meta = {
     5	  name: "Quote card",
     6	  durationInFrames: 150,
     7	};
     8	
     9	export const schema = {
    10	  quote:       { type: "string", default: "The best way to get started is to quit talking and begin doing.", multiline: true },
    11	  attribution: { type: "string", default: "Walt Disney" },
    12	  background:  { type: "color",  default: "#101014" },
    13	  accent:      { type: "color",  default: "#ffd60a" },
    14	};
    15	
    16	// One “6”-shaped quote half: a ball with a tail rising to the upper right, `s` tall.
    17	function mark(x, y, s) {
    18	  const r = s * 0.3;
    19	  const cx = x + r;
    20	  const cy = y + s - r;
    21	  return `<circle cx="${cx}" cy="${cy}" r="${r}"/>
    22	    <path d="M ${cx - r} ${cy} C ${cx - r} ${cy - r * 2.2} ${cx + r * 0.2} ${y + s * 0.08} ${cx + r * 1.25} ${y}
    23	             L ${cx + r * 1.25} ${y + s * 0.18} C ${cx + r * 0.25} ${y + s * 0.3} ${cx - r * 0.15} ${cy - r * 1.3} ${cx + r * 0.2} ${cy - r * 0.95} Z"/>`;
    24	}
    25	
    26	export function render(frame, props, ctx) {
    27	  const u = Math.min(ctx.width, ctx.height) / 1080;
    28	  const D = ctx.durationInFrames;
    29	  const safeY = ctx.height * 0.05;
    30	  const safeW = ctx.width * 0.9;
    31	  const safeH = ctx.height * 0.9;
    32	  const textW = safeW * 0.8;
    33	  const left = (ctx.width - textW) / 2;
    34	  const markH = 110 * u;
    35	  const attrSize = 40 * u;
    36	  const reserved = markH + 50 * u + 100 * u + attrSize + 2 * 60 * u;
    37	  let size = 84 * u;
    38	  let lines = [];
    39	  for (; size > 28 * u; size -= 4 * u) {
    40	    lines = wrapText(props.quote, textW, { family: "Montserrat", size, weight: 800 });
    41	    if (lines.length * size * 1.25 <= safeH - reserved) break;
    42	  }
    43	  if (size <= 28 * u) {
    44	    size = 28 * u;
    45	    lines = wrapText(props.quote, textW, { family: "Montserrat", size, weight: 800 });
    46	  }
    47	  const lineH = size * 1.25;
    48	  const blockH = markH + 50 * u + lines.length * lineH + 100 * u + attrSize;
    49	  const top = safeY + Math.max(60 * u, (safeH - blockH) / 2);
    50	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    51	  const markIn = spring({ frame, fps: ctx.fps, stiffness: 160, damping: 12 });
    52	  const mx = left;
    53	  const my = top;
    54	  const mcx = mx + markH * 0.6;
    55	  const mcy = my + markH / 2;
    56	  let body = "";
    57	  lines.forEach((line, i) => {
    58	    const t = interpolate(frame, [10 + i * 6, 28 + i * 6], [0, 1], { easing: Easing.outCubic, clamp: true });
    59	    const y = top + markH + 50 * u + size * 0.9 + i * lineH + (1 - t) * 24 * u;
    60	    body += `<text x="${left}" y="${y}" font-family="Montserrat" font-weight="800" font-size="${size}" fill="#ffffff"
    61	                   fill-opacity="${t * out}">${escapeXml(line)}</text>`;
    62	  });
    63	  const endLines = 28 + lines.length * 6;
    64	  const attrIn = interpolate(frame, [endLines - 6, endLines + 14], [0, 1], { easing: Easing.outCubic, clamp: true });
    65	  const attrY = top + markH + 50 * u + lines.length * lineH + 60 * u + 40 * u;
    66	  const slide = (1 - attrIn) * -40 * u;
    67	  const attrText = props.attribution.trim() ? `— ${props.attribution}` : "";
