    27	  const safeW = W * 0.9;
    28	  const safeH = H * 0.9;
    29	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    30	  const titleSize = props.title ? fitText(props.title, safeW - 120 * u, { family: "Montserrat", weight: 900 },
    31	    { min: 16 * u, max: 84 * u }) : 0;
    32	  const labelFont = { family: "Montserrat", size: 34 * u, weight: 800 };
    33	  const gap = 48 * u;
    34	  const boxW = landscape ? W * 0.3 : W * 0.8;
    35	  const boxH = (boxW * 9) / 16;
    36	  const circleD = landscape ? boxH * 0.86 : 260 * u;
