    43	    const rowH = boxH + labelH;
    44	    const blockH = titleSize + 70 * u + rowH;
    45	    const top = safeY + (safeH - blockH) / 2;
    46	    titleY = top + titleSize * 0.8;
    47	    const rowTop = top + titleSize + 70 * u;
    48	    const x = (W - rowW) / 2;
    49	    circle = { cx: x + circleD / 2, cy: rowTop + boxH / 2 };
    50	    boxes = [
    51	      { x: x + circleD + gap, y: rowTop, label: props.videoA },
    52	      { x: x + circleD + gap + boxW + gap, y: rowTop, label: props.videoB },
    53	    ];
    54	  } else {
    55	    const blockH = titleSize + 60 * u + 2 * (boxH + labelH) + gap + circleD + labelH;
    56	    const top = safeY + (safeH - blockH) / 2;
    57	    titleY = top + titleSize * 0.8;
    58	    const x = (W - boxW) / 2;
    59	    const first = top + titleSize + 60 * u;
    60	    boxes = [
    61	      { x, y: first, label: props.videoA },
    62	      { x, y: first + boxH + labelH + gap / 2, label: props.videoB },
    63	    ];
