    65	  }
    66	  const titleIn = interpolate(frame, [0, 16], [0, 1], { easing: Easing.outCubic, clamp: true });
    67	  let body = props.title ? `<text x="${W / 2}" y="${titleY + (1 - titleIn) * 20 * u}" text-anchor="middle"
    68	    font-family="Montserrat" font-weight="900" font-size="${titleSize}" fill="#ffffff"
    69	    fill-opacity="${titleIn * out}">${escapeXml(props.title)}</text>` : "";
    70	  boxes.forEach((b, i) => {
    71	    const t = spring({ frame: frame - 8 - i * 6, fps: ctx.fps, stiffness: 150, damping: 15 });
    72	    if (t <= 0.001) return;
