    25	      L ${s(-0.24)} ${s(0.24)} L ${s(-0.32)} ${s(0.24)} Q ${s(-0.46)} ${s(0.24)} ${s(-0.46)} ${s(0.1)}
    26	      L ${s(-0.46)} ${s(-0.24)} Q ${s(-0.46)} ${s(-0.38)} ${s(-0.32)} ${s(-0.38)} Z" fill="${colour}"/>`;
